package mcpsignals

import (
	"context"
	"encoding/json"
	"errors"
	"strings"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
)

// Identity is supplied only by the application. Empty fields become null.
type Identity struct {
	UserID string
	OrgID  string
}

// CallContext contains detached metadata for an application identity resolver.
// No user identity is inferred from client metadata, arguments or headers.
type CallContext struct {
	SessionID     string
	ClientName    string
	ClientVersion string
	Transport     string
}

// Options configures instrumentation. Supply the same name/version passed to
// mcp.NewServer: the SDK does not expose the server's Implementation publicly.
// Configure once, before connecting clients. Callbacks must be concurrency-safe.
type Options struct {
	ServerName       string
	ServerVersion    string
	Buffer           BufferOptions
	CaptureArguments bool
	Redaction        Redaction
	ResolveIdentity  func(context.Context, CallContext) (Identity, error)
	// Transport may be "stdio" or "http" when the application knows the transport.
	// Otherwise HTTP is detected from RequestExtra.Header; other transports are null.
	Transport string
}

// Handle owns the telemetry lifecycle, not the MCP server or its sinks.
type Handle struct {
	Server  *mcp.Server
	buffer  *EventBuffer
	options Options
}

// Instrument adds supported receiving middleware without changing tool handlers
// or registration APIs. Existing and subsequently registered tools are observed.
// Call once per server, after other receiving middleware, before serving clients.
func Instrument(server *mcp.Server, o Options) (*Handle, error) {
	if server == nil || o.ServerName == "" {
		return nil, errors.New("mcpsignals: server and server name are required")
	}
	if o.Transport != "" && o.Transport != "stdio" && o.Transport != "http" {
		return nil, errors.New("mcpsignals: transport must be stdio, http, or empty")
	}
	o.Redaction.Allow = append([]string(nil), o.Redaction.Allow...)
	o.Redaction.Deny = append([]string(nil), o.Redaction.Deny...)
	b, err := NewEventBuffer(o.Buffer)
	if err != nil {
		return nil, err
	}
	h := &Handle{Server: server, buffer: b, options: o}
	server.AddReceivingMiddleware(h.middleware)
	return h, nil
}

// Flush waits for previously started writes and flushes queued events.
func (h *Handle) Flush(ctx context.Context) error { return h.buffer.Flush(ctx) }

// Close drains telemetry after the application has stopped and drained requests.
func (h *Handle) Close(ctx context.Context) error { return h.buffer.Close(ctx) }

// Stats returns buffer overflow and sink failure counters.
func (h *Handle) Stats() BufferStats { return h.buffer.Stats() }

func (h *Handle) middleware(next mcp.MethodHandler) mcp.MethodHandler {
	return func(ctx context.Context, method string, req mcp.Request) (mcp.Result, error) {
		call, ok := req.(*mcp.CallToolRequest)
		if method != "tools/call" || !ok || call == nil || call.Params == nil {
			return next(ctx, method, req)
		}
		event := h.prepare(ctx, call)
		start := time.Now()
		event.TS = start.UTC()
		// Deliberately no recovery around next: handler errors/panics belong to the SDK.
		result, err := next(ctx, method, req)
		event.DurationMS = time.Since(start).Milliseconds()
		h.record(event, result, err)
		return result, err
	}
}

func (h *Handle) prepare(ctx context.Context, req *mcp.CallToolRequest) (e ToolCallEvent) {
	e = ToolCallEvent{EventType: "tool_call", ServerName: h.options.ServerName, ServerVersion: optional(h.options.ServerVersion), ToolName: truncate(req.Params.Name, 128), RequestBytes: len(req.Params.Arguments)}
	// Telemetry never changes the invocation, even if SDK metadata access fails.
	defer func() { _ = recover() }()
	e.Arguments = captureArguments(req.Params.Arguments, h.options.CaptureArguments, h.options.Redaction)
	c := CallContext{Transport: h.options.Transport}
	if req.Extra != nil && req.Extra.Header != nil {
		c.Transport = "http"
	}
	if req.Session != nil {
		c.SessionID = req.Session.ID()
	}
	if info := req.ClientInfo(); info != nil {
		c.ClientName = info.Name
		c.ClientVersion = info.Version
	}
	e.Transport = optional(c.Transport)
	e.SessionID = optional(c.SessionID)
	e.ClientName = bounded(c.ClientName, 128)
	e.ClientVersion = bounded(c.ClientVersion, 128)
	identity := resolveIdentity(ctx, h.options.ResolveIdentity, c)
	e.UserID = optional(identity.UserID)
	e.OrgID = optional(identity.OrgID)
	return e
}

func resolveIdentity(ctx context.Context, f func(context.Context, CallContext) (Identity, error), c CallContext) (identity Identity) {
	defer func() {
		if recover() != nil {
			identity = Identity{}
		}
	}()
	if f != nil {
		value, err := f(ctx, c)
		if err == nil {
			return value
		}
	}
	return Identity{}
}

func (h *Handle) record(e ToolCallEvent, result mcp.Result, callErr error) {
	defer func() { _ = recover() }()
	e.Success = callErr == nil
	var message string
	var declared string
	if callErr != nil {
		message = safeErrorMessage(callErr)
	} else if r, ok := result.(*mcp.CallToolResult); ok && r != nil {
		e.ResponseBytes = serializedSize(r)
		e.Success = !r.IsError
		if r.IsError {
			var parts []string
			for _, content := range r.Content {
				if text, ok := content.(*mcp.TextContent); ok && text != nil {
					parts = append(parts, text.Text)
				}
			}
			message = strings.Join(parts, " ")
			switch value := r.Meta[ErrorKindMetaKey].(type) {
			case string:
				declared = value
			case ErrorKind:
				declared = string(value)
			}
		}
	}
	if !e.Success {
		e.ErrorMessage = bounded(message, 2000)
		kind := ClassifyError(valueOrEmpty(e.ErrorMessage))
		if IsErrorKind(declared) {
			kind = ErrorKind(declared)
		}
		if kind != "" {
			e.ErrorKind = &kind
		}
	}
	h.buffer.Push(e)
}

func valueOrEmpty(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}
func safeErrorMessage(err error) (message string) {
	defer func() { _ = recover() }()
	return err.Error()
}
func serializedSize(v any) (size int) {
	defer func() { _ = recover() }()
	data, err := json.Marshal(v)
	if err == nil {
		return len(data)
	}
	return 0
}
package mcpsignals

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// BufferOptions configures best-effort delivery. Zero values select defaults.
type BufferOptions struct {
	Sinks         []Sink
	BufferSize    int           // Automatic size threshold; default 20.
	FlushInterval time.Duration // Default 5 seconds.
	Manual        bool          // Disable all automatic writes, including size-triggered writes.
	MaxQueueSize  int           // Drop newest on overflow; default 1000 pending events.
	WriteTimeout  time.Duration // Automatic flush timeout; default 10 seconds.
}

// BufferStats reports cumulative delivery failures, without logging payloads.
type BufferStats struct {
	Dropped    uint64
	SinkErrors uint64
}

// EventBuffer is a bounded, concurrency-safe queue. Push never calls a sink.
// Flush and Close return sink errors; automatic failures are counted in Stats.
// A failed batch is not retried (a sink may have partially committed it).
type EventBuffer struct {
	mu      sync.Mutex
	queue   []ToolCallEvent
	closed  bool
	stats   BufferStats
	options BufferOptions
	gate    chan struct{}
	wake    chan struct{}
	stop    chan struct{}
	done    chan struct{}
}

// NewEventBuffer starts one worker unless Manual is set. No network calls are
// made until events are flushed. Call Close after stopping/draining the server.
func NewEventBuffer(o BufferOptions) (*EventBuffer, error) {
	if o.BufferSize < 0 || o.FlushInterval < 0 || o.MaxQueueSize < 0 || o.WriteTimeout < 0 {
		return nil, errors.New("mcpsignals: buffer settings must not be negative")
	}
	if o.BufferSize == 0 {
		o.BufferSize = 20
	}
	if o.FlushInterval == 0 {
		o.FlushInterval = 5 * time.Second
	}
	if o.MaxQueueSize == 0 {
		o.MaxQueueSize = 1000
	}
	if o.WriteTimeout == 0 {
		o.WriteTimeout = 10 * time.Second
	}
	o.Sinks = append([]Sink(nil), o.Sinks...)
	for _, sink := range o.Sinks {
		if sink == nil {
			return nil, errors.New("mcpsignals: nil sink")
		}
	}
	b := &EventBuffer{options: o, gate: make(chan struct{}, 1), wake: make(chan struct{}, 1), stop: make(chan struct{}), done: make(chan struct{})}
	if o.Manual {
		close(b.done)
	} else {
		go b.run()
	}
	return b, nil
}

// Push accepts an immutable event snapshot. False means closed or full;
// overflow is counted in Stats. Callers must not mutate accepted event data.
func (b *EventBuffer) Push(e ToolCallEvent) bool {
	b.mu.Lock()
	defer b.mu.Unlock()
	if b.closed {
		return false
	}
	if len(b.queue) >= b.options.MaxQueueSize {
		b.stats.Dropped++
		return false
	}
	b.queue = append(b.queue, e)
	if !b.options.Manual && len(b.queue) >= b.options.BufferSize {
		select {
		case b.wake <- struct{}{}:
		default:
		}
	}
	return true
}

// Stats returns a concurrency-safe copy of the counters.
func (b *EventBuffer) Stats() BufferStats { b.mu.Lock(); defer b.mu.Unlock(); return b.stats }

// Flush waits for earlier writes and attempts all events queued when it obtains
// the flush lock. A canceled context before dequeue preserves pending events.
// After dequeue the batch is attempted once, even on cancellation or failure.
// Sinks must honor ctx; Go cannot interrupt arbitrary user code.
func (b *EventBuffer) Flush(ctx context.Context) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	select {
	case b.gate <- struct{}{}:
	case <-ctx.Done():
		return ctx.Err()
	}
	defer func() { <-b.gate }()
	if err := ctx.Err(); err != nil {
		return err
	}
	b.mu.Lock()
	batch := b.queue
	b.queue = nil
	b.mu.Unlock()
	if len(batch) == 0 {
		return nil
	}
	var errs []error
	for i, sink := range b.options.Sinks {
		if err := writeSink(ctx, sink, batch); err != nil {
			b.mu.Lock()
			b.stats.SinkErrors++
			b.mu.Unlock()
			errs = append(errs, fmt.Errorf("mcpsignals: sink %d: %w", i, err))
		}
	}
	return errors.Join(errs...)
}

func writeSink(ctx context.Context, sink Sink, batch []ToolCallEvent) (err error) {
	defer func() {
		if recover() != nil {
			err = errors.New("sink panicked")
		}
	}()
	return sink.Write(ctx, batch)
}

// Close stops accepting events and stops the worker, then drains pending and
// in-flight writes. It is idempotent and may be retried with a fresh context
// after a timeout. Stop and drain MCP requests before calling Close.
// Sink ownership remains with the application; Close does not close sinks.
func (b *EventBuffer) Close(ctx context.Context) error {
	b.mu.Lock()
	if !b.closed {
		b.closed = true
		close(b.stop)
	}
	b.mu.Unlock()
	select {
	case <-b.done:
	case <-ctx.Done():
		return ctx.Err()
	}
	return b.Flush(ctx)
}

func (b *EventBuffer) run() {
	defer close(b.done)
	ticker := time.NewTicker(b.options.FlushInterval)
	defer ticker.Stop()
	for {
		select {
		case <-b.stop:
			return
		case <-ticker.C:
		case <-b.wake:
		}
		// Prefer shutdown over a buffered wakeup.
		select {
		case <-b.stop:
			return
		default:
		}
		ctx, cancel := context.WithTimeout(context.Background(), b.options.WriteTimeout)
		_ = b.Flush(ctx)
		cancel()
	}
}
// Package mcpsignals records MCP tool usage into application-owned sinks.
// It supports the official github.com/modelcontextprotocol/go-sdk/mcp package.
package mcpsignals

import (
	"encoding/json"
	"regexp"
	"time"
)

// ErrorKind is a coarse failure category, not a replacement for Success.
type ErrorKind string

const (
	NotFound        ErrorKind = "not_found"
	Empty           ErrorKind = "empty"
	Validation      ErrorKind = "validation"
	AuthRequired    ErrorKind = "auth_required"
	PaymentRequired ErrorKind = "payment_required"
	Internal        ErrorKind = "internal"
	// ErrorKindMetaKey declares a category in an MCP error result's Meta map.
	ErrorKindMetaKey = "mcpsignals/error_kind"
)

// IsErrorKind reports whether value is a supported category.
func IsErrorKind(value string) bool {
	switch ErrorKind(value) {
	case NotFound, Empty, Validation, AuthRequired, PaymentRequired, Internal:
		return true
	}
	return false
}

var errorPatterns = []struct {
	pattern *regexp.Regexp
	kind    ErrorKind
}{
	{regexp.MustCompile(`(?i)not found|does not exist|no such`), NotFound},
	{regexp.MustCompile(`(?i)\bempty\b|no results?|nothing found|zero results`), Empty},
	{regexp.MustCompile(`(?i)invalid|required|expected|must be|validation|schema`), Validation},
}

// ClassifyError applies the shared schema's ordered message heuristic.
// An empty message returns "", which is represented as null in events.
// Authentication and payment categories must be explicitly declared.
func ClassifyError(message string) ErrorKind {
	if message == "" {
		return ""
	}
	for _, p := range errorPatterns {
		if p.pattern.MatchString(message) {
			return p.kind
		}
	}
	return Internal
}

// ToolCallEvent implements schema/events.md. Nullable fields have no omitempty:
// missing data is JSON null, never an absent key or an "unknown" sentinel.
// Sinks must treat events and their referenced data as read-only.
type ToolCallEvent struct {
	EventType     string          `json:"event_type"`
	TS            time.Time       `json:"ts"`
	ServerName    string          `json:"server_name"`
	ServerVersion *string         `json:"server_version"`
	ToolName      string          `json:"tool_name"`
	SessionID     *string         `json:"session_id"`
	AgentID       *string         `json:"agent_id"`
	ClientName    *string         `json:"client_name"`
	ClientVersion *string         `json:"client_version"`
	UserID        *string         `json:"user_id"`
	OrgID         *string         `json:"org_id"`
	DurationMS    int64           `json:"duration_ms"`
	Success       bool            `json:"success"`
	ErrorKind     *ErrorKind      `json:"error_kind"`
	ErrorMessage  *string         `json:"error_message"`
	RequestBytes  int             `json:"request_bytes"`
	ResponseBytes int             `json:"response_bytes"`
	Arguments     json.RawMessage `json:"arguments"`
	Intent        *string         `json:"intent"`
	Transport     *string         `json:"transport"`
}

func optional(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}
func bounded(s string, n int) *string { return optional(truncate(s, n)) }

func truncate(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n])
	}
	return s
}

